import React, { useState } from 'react';

import { images } from '../../constants';
import { AppWrap, MotionWrap } from '../../wrapper';
import './Footer.scss';

const Footer = () => {
  const [formData, setFormData] = useState({ name: '', email: '', message: '' });
  const [isFormSubmitted, setIsFormSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);

  const { username, email, message } = formData;

  const handleChangeInput = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setLoading(true);

    // Create mailto link with form data
    const subject = encodeURIComponent(`Portfolio Contact from ${formData.username}`);
    const body = encodeURIComponent(`Name: ${formData.username}\nEmail: ${formData.email}\n\nMessage:\n${formData.message}`);
    const mailtoLink = `mailto:singla.samarth28@gmail.com?subject=${subject}&body=${body}`;

    // Open email client
    window.location.href = mailtoLink;
    // Simulate form submission
    setTimeout(() => {
      setLoading(false);
      setIsFormSubmitted(true);
    }, 1000);
  };

  return (
    <>
      <h2 className="head-text"> Let&apos;s <span> collaborate</span>  !</h2>

      <div className="app__footer-cards">
        <div className="app__footer-card ">
          <img src={images.email} alt="email" />
          <a href="mailto:singla.samarth28@gmail.com" className="p-text">singla.samarth28@gmail.com</a>
        </div>
        <div className="app__footer-card">

          <img src={images.mobile} alt="phone" />
          <a href="tel:+91 7011844043" className="p-text">+91 7011844043</a>
        </div>
        <div className="app__footer-card">
          <img src={images.linked} alt="LinkedIn" />
          <a href="https://www.linkedin.com/in/samarthsinghal28/" className="p-text">Samarth Singhal</a>
        </div>
        <div className="app__footer-card">
          <img src={images.github} alt="LinkedIn" />
          <a href="https://github.com/Samarthsinghal28" className="p-text">Samarthsinghal28</a>
        </div>
      </div>
      {!isFormSubmitted ? (
        <form className="app__footer-form app__flex" onSubmit={handleSubmit}>
          <div className="app__flex">
            <input className="p-text" type="text" placeholder="Your Name" name="username" value={username} onChange={handleChangeInput} required />
          </div>
          <div className="app__flex">
            <input className="p-text" type="email" placeholder="Your Email" name="email" value={email} onChange={handleChangeInput} required />
          </div>
          <div>
            <textarea
              className="p-text"
              placeholder="Your Message"
              value={message}
              name="message"
              onChange={handleChangeInput}
              required
            />
          </div>
          <button type="submit" className="p-text" disabled={loading}>
            {!loading ? 'Send Message' : 'Opening Email...'}
          </button>
        </form>
      ) : (
        <div>
          <h3 className="head-text">
            Thank you for getting in touch!
          </h3>
          <p className="p-text">Your email client should have opened with the message ready to send.</p>
          <button
            type="button"
            className="p-text"
            onClick={() => setIsFormSubmitted(false)}
            style={{ marginTop: '1rem' }}
          >
            Send Another Message
          </button>
        </div>
      )}
    </>
  );
};

export default AppWrap(
  MotionWrap(Footer, 'app__footer'),
  'contact',
  'app__whitebg',
);
